import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/LayerNormalization.html","title":"LayerNormalization","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":2.04,"words":611},"filePathRelative":"LayerNormalization.md"}`),a={name:`LayerNormalization.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="layernormalization" tabindex="-1"><a class="header-anchor" href="#layernormalization"><span>LayerNormalization</span></a></h1><p><a href="./BatchNormalization.html">BatchNormalization</a>からヒントを得て、同様の平均と分散の割引を単一のベクトルの次元側でやる手法。<a href="./Transformer.html">Transformer</a>で使われる。</p><p>バイアスとゲインは学習パラメータ。</p><ul><li><a href="https://arxiv.org/abs/1607.06450" target="_blank" rel="noopener noreferrer">arxiv:1607.06450 Layer Normalization</a> 元論文。2016年。 このページではこの<a href="./論文.html">論文</a>の話をメインに他のソースの話も混ぜる。トロント大学。</li></ul><p><a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>の3.4 (式3.17）にも解説がある。</p><p>基本的には<a href="./BatchNormalization.html">BatchNormalization</a>の <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>μ</mi></mrow><annotation encoding="application/x-tex">\\mu</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span></span></span></span> と <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>σ</mi></mrow><annotation encoding="application/x-tex">\\sigma</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span></span></span></span> を、各iの <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>d</mi><mrow><mi>m</mi><mi>o</mi><mi>d</mi><mi>e</mi><mi>l</mi></mrow></msub></mrow><annotation encoding="application/x-tex">d_{model}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">m</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 側に足して求めたもので代用する。</p><p><img src="/RandomThoughts/assets/0000-BVjK7S7T.png" alt="imgs/LayerNorm/0000.png"></p><p>ここで<a href="./BatchNormalization.html">BatchNormalization</a>では <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>σ</mi></mrow><annotation encoding="application/x-tex">\\sigma</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span></span></span></span> も <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>μ</mi></mrow><annotation encoding="application/x-tex">\\mu</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span></span></span></span> もベクトルだったが、LayerNormalizationは要素方向にとるのでスカラーになる事に注意。</p><h3 id="和の取る方向" tabindex="-1"><a class="header-anchor" href="#和の取る方向"><span>和の取る方向</span></a></h3><p>もともとはRNNで<a href="./BatchNormalization.html">BatchNormalization</a>が使えないのでどうにかしたい、という問題設定で生まれたものなので、レイヤー内での平均を取る形に見えたが、 昨今は<a href="./Transformerブロック.html">Transformerブロック</a>で使われる用途が主流になり、これはレイヤー内での和では無いのでちょっと注意が必要。</p><p>Transformerブロックではトークン単位というかd方向に和を取り、n方向には和をとらない。</p><p>これはRNNでの和の取り方と一致しているけれど、Transformerは1レイヤーに複数トークンがある事を思うと結構違う取り方には見える。 なお、gainとbiasパラメータはTransformerではn方向では全部同じものを使うっぽい。</p><h2 id="batch-normalizationとどっちを使うべきか" tabindex="-1"><a class="header-anchor" href="#batch-normalizationとどっちを使うべきか"><span>Batch Normalizationとどっちを使うべきか？</span></a></h2><p>Layer NormalizationはもともとRNNのようにバッチという概念が中間層に使えないものに使う技法として開発されたが、 <a href="./Transformer.html">Transformer</a>とかにも使われている。</p><p>どうもTransformerではそのままBNに置き換えるとパフォーマンスが悪い事は知られているよう。</p><p><a href="https://arxiv.org/abs/2003.07845" target="_blank" rel="noopener noreferrer">arxiv:2003.07845 PowerNorm: Rethinking Batch Normalization in Transformers</a></p><p>サンプルごとの値の違いが大きすぎて統計がバッチごとにばらつきが大きいから上手くいかないらしい。</p><p>一方Vision Transformerなどでは工夫したBNの方がいいという話もあるとか。</p><p>LayerNormの元論文の6.7にCNNでの比較があり、通常のCNNではbatch normalizationの方が良いとか。</p><p>それは境界のそばのフィーチャーは0に近いなど、同じレイヤーでも場所によって統計が大きく違うという、 Layer Normalizeに不向きな偏りがあるからではないか、とか書いてある。</p><p>この辺はいろいろ研究の余地もあるようで、<a href="https://arxiv.org/abs/2201.03545" target="_blank" rel="noopener noreferrer">arxiv:2201.03545 A ConvNet for the 2020s</a>などではLayer Normalizationの方が良くなるような構造もあるとか。</p><h3 id="推論時の計算コスト" tabindex="-1"><a class="header-anchor" href="#推論時の計算コスト"><span>推論時の計算コスト</span></a></h3><p>Vision TransformerにBatch Normalizationを使う系の論文の以下を見ていたら、 <a href="https://arxiv.org/html/2405.11582v2" target="_blank" rel="noopener noreferrer">SLAB: Efficient Transformers with Simplified Linear Attention and Progressive Re-parameterized Batch Normalization</a>、 Inference時の計算コストのためにLayer NormalizationをBatch Normalizationに変えようと模索している論文だった。</p><p>inference時の計算コストの違いというのは考えてなかったのでここで考えてみたい。</p><p><a href="./BatchNormalization.html">BatchNormalization</a>では平均と分散の計算はトレーニング時のみで、inference時は不要となる。 一方LayerNormlizationは毎回計算する必要がある。</p><p>1ベクトルあたり平均と分散はそれぞれO(d)程度か。それがnトークンあるのだから、コストはO(nd)かな。</p><h2 id="論文のリーマンmetricとフィッシャー統計量での学習のregularizationの話-はあまり理解出来てない" tabindex="-1"><a class="header-anchor" href="#論文のリーマンmetricとフィッシャー統計量での学習のregularizationの話-はあまり理解出来てない"><span>論文のリーマンmetricとフィッシャー統計量での学習のregularizationの話（はあまり理解出来てない）</span></a></h2><p>この論文のセクション5には、LayerNormalizationがregularizationとして振る舞っている、という理論的な分析があって、結構数学的にはゴツい。 一応フィッシャー統計量とかリーマンmetricはそれなりに勉強した事はあるので知らない話では無いはずだが、 全部復習して追うガッツは沸かず。</p><p>内容的にはパラメータのノルムが2倍になると、パラメータ方向のフィッシャー統計量の曲率が半分となり、 つまり学習の勾配が小さくなる、みたいな話をしていると理解した。</p><p>ただなんでGLMがうんぬん、という話がでているのかは良く分からない。RNNはGLMの足し合わせで表せるのかしら？GLMあんま知らないからなぁ（本は買ったが読んでない）</p><h2 id="論文の実験結果" tabindex="-1"><a class="header-anchor" href="#論文の実験結果"><span>論文の実験結果</span></a></h2><p>実験は幾つかのタスクでやっている。</p><ul><li>image-sentence ranking</li><li>question answering（穴埋め）</li><li>contextual language modeling（skip-thoughts vector、文を読ませて前後の文を予想させる、というタスクか）</li><li>generative modelling（MNISTから画像を作る</li><li>handwriting sequence generation</li><li>MNIST classification (permutation invariant MNIST、これだけFFNにつけての比較）</li></ul><p>学習の収束が60%くらいに高速化されて、しかもgeneralizationもより良くされるよう。Image-Sentence的なまぁまぁマルチモーダルな実験をやっているのが、 この頃こんな事流行ってたなぁ、という気持ちになる。</p><p>BNとの比較ではquestion-answeringで、穴埋め問題をやっているよう。LSTMのモデルとかにどうBNを適用しているかは良く分からない。スコアとしてはLayerNormの方がいいのだが、BatchNormも結構優秀なんだよなぁ。</p><p>結構たくさんの実験をやっているので、なかなか大変そうだ。良くこれだけ調べたなぁ。一ヶ月くらいトレーニングに使っている実験もある。</p><p>permutation invariant MNISTというのがどういうテストかあまりしらないが、FNNでもLayerNormalizationは改善していそうだ。</p><p>6.7には特に実験の内容は記さずに、CNNでも試したらBatchNormに負けてた、みたいな事が書いてある。考察としてはhidden unitの役割が場所によって違うので統計の振る舞いが違うからじゃないか、とか書いてある。</p><h3 id="論文の雑感、めっちゃ頑張って研究してあるなぁ" tabindex="-1"><a class="header-anchor" href="#論文の雑感、めっちゃ頑張って研究してあるなぁ"><span>論文の雑感、めっちゃ頑張って研究してあるなぁ</span></a></h3><p>理論的な事もしっかりやっているし、実験もたくさんのモデルでたくさんのタスクを頑張って評価している。これはめっちゃ大変だっただろうなぁ。 昨今の機械学習系の論文ではめったに見ないレベルのしっかりした研究だ。（昨今では無いから、というのはあるが。学習量が現代とは違う）</p><p>トロント大学、なかなか優秀ね。</p>`,41)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};